import { IntegerColumn, ReferenceColumn, Table } from '@servicenow/sdk/core'

export const sn_table_app_incoming = Table({
    actions: ['read', 'update', 'create'],
    index: [{ name: 'index', element: 'reference_column', unique: false }],
    name: 'sn_table_app_incoming',
    label: 'Incoming Table',
    extends: 'cmdb',
    schema: {
        integer_column: IntegerColumn({
            label: 'Integer Column',
            audit: true,
            readOnly: false,
            dropdown: 'suggestion',
            choices: {
                2: { label: 'Two', value: '2', inactive_on_update: false },
            },
        }),
        reference_column: ReferenceColumn({
            audit: false,
            readOnly: false,
            referenceTable: 'task',
            choices: {
                1: {
                    label: 'One',
                },
            },
        }),
    },
    display: 'integer_column',
})
